var FIREBASE_SDK_VERSION = '12.17.0';
var firebaseSdkPromise = null;
function loadScript(src){
  return new Promise(function(resolve, reject){
    var s = document.createElement('script');
    s.src = src;
    s.onload = resolve;
    s.onerror = reject;
    document.head.appendChild(s);
  });
}
function loadFirebaseSdk(){
  if(firebaseSdkPromise) return firebaseSdkPromise;
  var base = 'https://www.gstatic.com/firebasejs/'+FIREBASE_SDK_VERSION+'/';
  firebaseSdkPromise = loadScript(base+'firebase-app-compat.js')
    .then(function(){ return loadScript(base+'firebase-auth-compat.js'); })
    .then(function(){ return loadScript(base+'firebase-firestore-compat.js'); });
  return firebaseSdkPromise;
}

var fbAuth = null, fbDb = null;
function initFirebase(){
  if(fbAuth) return Promise.resolve();
  return loadFirebaseSdk().then(function(){
    firebase.initializeApp(FIREBASE_CONFIG);
    fbAuth = firebase.auth();
    fbDb = firebase.firestore();
  });
}

