/* ================= UTIL ================= */

function escapeHtml(s){
  if(s===undefined||s===null) return '';
  return String(s).replace(/[&<>"']/g,function(c){
    return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];
  });
}
function passesShowIf(f, dataObj){
  if(!f.showIf) return true;
  var val = dataObj[f.showIf.field];
  if(f.showIf.includes) return Array.isArray(val) && val.indexOf(f.showIf.includes)>-1;
  if(f.showIf.oneOf) return f.showIf.oneOf.indexOf(val)>-1;
  return val === f.showIf.equals;
}
function genId(){ return 'lvt_'+Date.now().toString(36)+Math.random().toString(36).slice(2,7); }

/* ================= TEMA (claro / oscuro) ================= */

var THEME_KEY = 'siti_theme';
function getPreferredTheme(){
  try {
    var saved = localStorage.getItem(THEME_KEY);
    if(saved==='dark' || saved==='light') return saved;
  } catch(e){}
  try {
    if(window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) return 'dark';
  } catch(e){}
  return 'light';
}
function applyTheme(theme){
  appRootEl.setAttribute('data-theme', theme);
  try { document.documentElement.style.colorScheme = theme; } catch(e){}
  try { localStorage.setItem(THEME_KEY, theme); } catch(e){}
  var btn = document.getElementById('siti-theme-toggle');
  if(btn) btn.textContent = theme==='dark' ? 'Modo claro' : 'Modo oscuro';
}
document.getElementById('siti-theme-toggle').addEventListener('click', function(){
  var isDark = appRootEl.getAttribute('data-theme')==='dark';
  applyTheme(isDark ? 'light' : 'dark');
});
applyTheme(getPreferredTheme());

// Al imprimir / guardar como PDF, siempre se ve en modo claro (sin importar lo que se use en pantalla).
window.addEventListener('beforeprint', function(){
  if(appRootEl.getAttribute('data-theme')==='dark'){
    appRootEl.setAttribute('data-print-restore','1');
    appRootEl.setAttribute('data-theme','light');
  }
});
window.addEventListener('afterprint', function(){
  if(appRootEl.getAttribute('data-print-restore')==='1'){
    appRootEl.removeAttribute('data-print-restore');
    appRootEl.setAttribute('data-theme','dark');
  }
});

function todayISO(){ var d=new Date(); return d.toISOString().slice(0,10); }
function fmtDate(iso){
  if(!iso) return '—';
  var parts=iso.split('-'); if(parts.length!==3) return iso;
  return parts[2]+'/'+parts[1]+'/'+parts[0];
}
function showToast(msg, isErr){
  toastEl.textContent = msg;
  toastEl.className = 'toast show' + (isErr?' err':'');
  setTimeout(function(){ toastEl.className='toast'; }, 2600);
}

function customConfirm(message){
  return new Promise(function(resolve){
    var appEl = document.getElementById('siti-app');
    var overlay = document.createElement('div');
    overlay.className = 'siti-confirm-overlay';
    overlay.innerHTML = '<div class="siti-confirm-box"><p>'+escapeHtml(message)+'</p>'+
      '<div class="siti-confirm-actions"><button type="button" class="btn secondary" data-a="cancel">Cancelar</button><button type="button" class="btn danger" data-a="ok">Confirmar</button></div></div>';
    appEl.appendChild(overlay);
    overlay.querySelector('[data-a="ok"]').onclick = function(){ overlay.remove(); resolve(true); };
    overlay.querySelector('[data-a="cancel"]').onclick = function(){ overlay.remove(); resolve(false); };
  });
}

/* ================= STORAGE ================= */

function hasClaudeStorage(){
  return typeof window!=='undefined' && window.storage && typeof window.storage.get==='function';
}

function storageGet(key){
  if(hasClaudeStorage()){
    return window.storage.get(key, true).then(function(r){ return r ? r.value : null; }).catch(function(){ return null; });
  }
  var v = null;
  try { v = localStorage.getItem('siti_'+key); } catch(e){ v = null; }
  return Promise.resolve(v);
}
function storageSet(key, value){
  if(hasClaudeStorage()){
    return window.storage.set(key, value, true);
  }
  try { localStorage.setItem('siti_'+key, value); return Promise.resolve(true); }
  catch(e){ return Promise.reject(e); }
}
function storageDelete(key){
  if(hasClaudeStorage()){
    return window.storage.delete(key, true).catch(function(){});
  }
  try { localStorage.removeItem('siti_'+key); } catch(e){}
  return Promise.resolve(true);
}

function loadIndex(){
  if(backend==='firebase') return loadIndexFirebase();
  return storageGet('survey-index').then(function(v){
    return v ? JSON.parse(v) : [];
  }).catch(function(){ return []; });
}
function saveIndex(){
  if(backend==='firebase') return Promise.resolve(); // Firestore no necesita índice aparte, se consulta directo
  return storageSet('survey-index', JSON.stringify(indexData));
}
function loadSurvey(id){
  if(backend==='firebase') return loadSurveyFirebase(id);
  return storageGet('survey:'+id).then(function(v){
    return v ? JSON.parse(v) : null;
  }).catch(function(){ return null; });
}
function persistSurvey(survey){
  if(backend==='firebase') return persistSurveyFirebase(survey);
  return storageSet('survey:'+survey.id, JSON.stringify(survey));
}
function removeSurveyStorage(id){
  if(backend==='firebase') return fbDb.collection('surveys').doc(id).delete().catch(function(){});
  return storageDelete('survey:'+id);
}

/* ---- Directorio de empresas (autocompletado de datos de contacto) ----
   En backend 'firebase' el catálogo es COMPARTIDO por todo el equipo (colección
   'empresas' en Firestore). En 'local'/'claude' se guarda en el dispositivo.
   Al escribir un cliente ya conocido, rellena los campos de contacto vacíos. */
var EMPRESA_AUTOFILL_FIELDS = ['contacto','telefono','email','direccion'];
function empresaKey(name){ return (name||'').trim().toLowerCase(); }
// ID de documento seguro en Firestore (sin caracteres no permitidos).
function empresaDocId(name){
  return (empresaKey(name).replace(/[\/\\.#$\[\]]+/g,'_') || '_').slice(0,1400);
}
function refreshEmpresasNames(){
  empresasNames = Object.keys(empresasDir).map(function(k){ return empresasDir[k].cliente; })
    .filter(Boolean).sort(function(a,b){ return a.localeCompare(b,'es'); });
}
function empresasDirFromSnap(snap){
  var dir = {};
  snap.forEach(function(doc){
    var d = doc.data(); var name = d.cliente || '';
    if(!name) return;
    var rec = {cliente: name};
    EMPRESA_AUTOFILL_FIELDS.forEach(function(k){ if(d[k]) rec[k] = d[k]; });
    dir[empresaKey(name)] = rec;
  });
  return dir;
}
// Suscripción en vivo al catálogo compartido: cualquier empresa nueva capturada
// por otro técnico aparece al instante en todos los dispositivos.
function subscribeEmpresas(){
  if(!fbDb) return;
  if(empresasUnsub){ empresasUnsub(); empresasUnsub = null; }
  empresasUnsub = fbDb.collection('empresas').onSnapshot(function(snap){
    empresasDir = empresasDirFromSnap(snap);
    refreshEmpresasNames();
    refreshEmpresasDatalist();
  }, function(){ /* reglas o sin conexión: se conserva lo último cargado */ });
}
function unsubscribeEmpresas(){
  if(empresasUnsub){ empresasUnsub(); empresasUnsub = null; }
}
// Refresca en el sitio la lista desplegable y el aviso del campo Cliente
// (sin re-render, para no perder el foco mientras se escribe).
function refreshEmpresasDatalist(){
  var dl = document.getElementById('empresas-datalist');
  if(dl){
    dl.innerHTML = empresasNames.map(function(n){ return '<option value="'+escapeHtml(n)+'"></option>'; }).join('');
  }
  var cli = mainEl.querySelector('[data-general="cliente"]');
  if(cli){
    var hint = mainEl.querySelector('[data-empresa-hint]');
    if(hint){
      hint.textContent = empresaHintText(cli.value);
      hint.classList.toggle('found', empresaExiste((cli.value||'').trim()));
    }
  }
}
// Carga por dispositivo (local / preview). En Firebase se usa subscribeEmpresas().
function loadEmpresas(){
  return storageGet('empresas-dir').then(function(v){
    empresasDir = v ? (JSON.parse(v) || {}) : {};
  }).catch(function(){ empresasDir = {}; }).then(function(){ refreshEmpresasNames(); });
}
function upsertEmpresa(general){
  var name = (general.cliente||'').trim();
  if(!name) return Promise.resolve();
  var rec = {cliente: name};
  EMPRESA_AUTOFILL_FIELDS.forEach(function(k){ if(general[k]) rec[k] = general[k]; });
  empresasDir[empresaKey(name)] = rec;
  refreshEmpresasNames();
  if(backend==='firebase' && fbDb){
    var doc = Object.assign({key: empresaKey(name), updatedAt: Date.now()}, rec);
    if(currentUser && currentUser.email) doc.updatedBy = currentUser.email;
    // merge:true acumula datos conocidos y nunca borra un contacto con un vacío.
    return fbDb.collection('empresas').doc(empresaDocId(name)).set(doc, {merge:true}).catch(function(){});
  }
  return storageSet('empresas-dir', JSON.stringify(empresasDir)).catch(function(){});
}
// Rellena los campos de contacto vacíos con los de la empresa conocida.
// Devuelve la lista de campos que se autocompletaron (para reflejarlos en el DOM
// sin re-renderizar el formulario, y no perder el cursor).
function autofillEmpresa(name){
  var rec = empresasDir[empresaKey(name)];
  if(!rec) return [];
  var changed = [];
  EMPRESA_AUTOFILL_FIELDS.forEach(function(k){
    if(!current.general[k] && rec[k]){ current.general[k] = rec[k]; changed.push(k); }
  });
  return changed;
}
function empresaExiste(name){ return !!empresasDir[empresaKey(name)]; }
function empresaHintText(name){
  var n = (name||'').trim();
  if(!n) return '';
  return empresaExiste(n)
    ? '✓ Empresa encontrada — datos de contacto autocompletados.'
    : '＋ Empresa nueva: se creará al guardar el levantamiento.';
}
// Actualiza en el sitio (sin re-render) el aviso y los campos autocompletados.
function updateEmpresaUI(name){
  autofillEmpresa(name).forEach(function(k){
    var el = mainEl.querySelector('[data-general="'+k+'"]');
    if(el && !el.value) el.value = current.general[k];
  });
  var hint = mainEl.querySelector('[data-empresa-hint]');
  if(hint){
    hint.textContent = empresaHintText(name);
    hint.classList.toggle('found', empresaExiste((name||'').trim()));
  }
}

/* ---- Firestore: alcance por dueño / rol ---- */

function loadIndexFirebase(){
  var col = fbDb.collection('surveys');
  var q = col;
  if(currentUser.role==='admin'){
    if(adminFilterOwnerId && adminFilterOwnerId!=='ALL'){
      q = col.where('ownerId','==',adminFilterOwnerId);
    }
  } else {
    q = col.where('ownerId','==',currentUser.uid);
  }
  return q.get().then(function(snap){
    var arr = [];
    snap.forEach(function(doc){
      var d = doc.data();
      arr.push({
        id: doc.id,
        cliente: (d.general&&d.general.cliente) || '(sin nombre de cliente)',
        direccion: (d.general&&d.general.direccion) || '',
        fecha: (d.general&&d.general.fecha) || '',
        tecnico: (d.general&&d.general.tecnico) || '',
        services: d.services || [],
        updatedAt: d.updatedAt || 0,
        ownerEmail: d.ownerEmail || ''
      });
    });
    return arr;
  });
}
function loadSurveyFirebase(id){
  return fbDb.collection('surveys').doc(id).get().then(function(doc){
    return doc.exists ? doc.data() : null;
  });
}
function persistSurveyFirebase(survey){
  var toSave = Object.assign({}, survey, {ownerId: survey.ownerId || currentUser.uid, ownerEmail: survey.ownerEmail || currentUser.email});
  return fbDb.collection('surveys').doc(survey.id).set(toSave);
}

function upsertIndexEntry(survey){
  var entry = {
    id: survey.id,
    cliente: survey.general.cliente || '(sin nombre de cliente)',
    direccion: survey.general.direccion || '',
    fecha: survey.general.fecha || '',
    tecnico: survey.general.tecnico || '',
    services: survey.services.slice(),
    updatedAt: survey.updatedAt
  };
  var found=false;
  for(var i=0;i<indexData.length;i++){
    if(indexData[i].id===survey.id){ indexData[i]=entry; found=true; break; }
  }
  if(!found) indexData.push(entry);
}

/* ================= AUTH (Firebase) ================= */

function ensureUserDoc(user){
  var ref = fbDb.collection('users').doc(user.uid);
  return ref.get().then(function(snap){
    if(snap.exists) return snap.data();
    return fbDb.collection('deletedUsers').doc(user.uid).get().then(function(delSnap){
      if(delSnap.exists) return {__deleted:true};
      var data = {email:user.email, role:'tecnico', disabled:false, createdAt: Date.now()};
      return ref.set(data).then(function(){ return data; });
    });
  });
}

function startFirebaseAuthListener(){
  fbAuth.onAuthStateChanged(function(user){
    if(user){
      ensureUserDoc(user).then(function(profile){
        if(profile.__deleted){
          showToast('Esta cuenta fue eliminada por el administrador.', true);
          fbAuth.signOut();
          return;
        }
        if(profile.disabled){
          showToast('Tu cuenta está deshabilitada. Contacta al administrador.', true);
          fbAuth.signOut();
          return;
        }
        currentUser = {uid:user.uid, email:user.email, role:profile.role||'tecnico', disabled:false};
        allUsersCache = null;
        adminFilterOwnerId = 'ALL';
        renderUserbar();
        // Suscribe el catálogo de empresas compartido (se actualiza en vivo).
        subscribeEmpresas();
        goList();
        broadcastAuth();
      }).catch(function(){
        showToast('No se pudo verificar tu cuenta.', true);
      });
    } else {
      currentUser = null;
      unsubscribeEmpresas();
      renderUserbar();
      view = 'login';
      renderLogin();
      broadcastAuth();
    }
  });
}

/* Avisa al shell (index.html) del estado de sesión, para mostrar/ocultar
   la barra de pestañas de Calculadora y Costos. Un solo login controla las 3. */
function broadcastAuth(){
  window.SITI = window.SITI || {};
  window.SITI.currentUser = currentUser;
  window.SITI.backend = backend;
  window.dispatchEvent(new CustomEvent('siti:auth', {detail:{user: currentUser}}));
}

function renderUserbar(){
  if(backend!=='firebase'){ userbarEl.innerHTML=''; return; }
  if(!currentUser){ userbarEl.innerHTML=''; return; }
  var adminBtn = currentUser.role==='admin' ? '<button type="button" class="btn ghost" id="btn-goto-admin" style="padding:7px 11px;font-size:12.5px;">Administración</button>' : '';
  userbarEl.innerHTML =
    '<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;justify-content:flex-end;">'+
      '<span style="font-size:12px;color:var(--text-muted);">'+escapeHtml(currentUser.email)+(currentUser.role==='admin'?' · Admin':'')+'</span>'+
      adminBtn+
      '<button type="button" class="btn ghost" id="btn-signout" style="padding:7px 11px;font-size:12.5px;">Salir</button>'+
    '</div>';
  var ab = document.getElementById('btn-goto-admin');
  if(ab) ab.onclick = goAdmin;
  document.getElementById('btn-signout').onclick = function(){ fbAuth.signOut(); };
}

function renderLogin(){
  mainEl.innerHTML =
    '<div style="max-width:360px;margin:40px auto;">'+
    '<h2 class="disp" style="font-size:19px;margin-bottom:4px;">Iniciar sesión</h2>'+
    '<p style="font-size:13px;color:var(--text-muted);margin-bottom:18px;">Usa tu correo y contraseña. Si es tu primera vez, crea una cuenta.</p>'+
    '<label class="field"><span>Correo</span><input type="email" id="auth-email" autocomplete="username"/></label>'+
    '<label class="field"><span>Contraseña</span><input type="password" id="auth-password" autocomplete="current-password"/></label>'+
    '<p id="auth-error" style="color:var(--danger);font-size:13px;display:none;margin-bottom:10px;"></p>'+
    '<button type="button" class="btn block" id="btn-login" style="margin-bottom:10px;">Iniciar sesión</button>'+
    '<button type="button" class="btn secondary block" id="btn-signup">Crear cuenta nueva</button>'+
    '</div>';

  function showAuthError(msg){
    var el = document.getElementById('auth-error');
    el.textContent = msg; el.style.display = 'block';
  }
  function authInputs(){
    return {
      email: document.getElementById('auth-email').value.trim(),
      password: document.getElementById('auth-password').value
    };
  }
  document.getElementById('btn-login').onclick = function(){
    var v = authInputs();
    if(!v.email || !v.password){ showAuthError('Ingresa correo y contraseña.'); return; }
    fbAuth.signInWithEmailAndPassword(v.email, v.password).catch(function(err){
      showAuthError(traduceAuthError(err));
    });
  };
  document.getElementById('btn-signup').onclick = function(){
    var v = authInputs();
    if(!v.email || !v.password){ showAuthError('Ingresa correo y contraseña.'); return; }
    if(v.password.length<6){ showAuthError('La contraseña debe tener al menos 6 caracteres.'); return; }
    fbAuth.createUserWithEmailAndPassword(v.email, v.password).catch(function(err){
      showAuthError(traduceAuthError(err));
    });
  };
}

function traduceAuthError(err){
  var code = err && err.code || '';
  var map = {
    'auth/invalid-email':'Correo inválido.',
    'auth/user-not-found':'No existe una cuenta con ese correo.',
    'auth/wrong-password':'Contraseña incorrecta.',
    'auth/invalid-credential':'Correo o contraseña incorrectos.',
    'auth/email-already-in-use':'Ya existe una cuenta con ese correo. Intenta iniciar sesión.',
    'auth/weak-password':'La contraseña debe tener al menos 6 caracteres.',
    'auth/too-many-requests':'Demasiados intentos. Intenta de nuevo en unos minutos.'
  };
  return map[code] || 'No se pudo completar la operación. Intenta de nuevo.';
}

/* ---- Administración de usuarios (solo admin) ---- */

function fetchAllUsers(){
  if(allUsersCache) return Promise.resolve(allUsersCache);
  return fbDb.collection('users').get().then(function(snap){
    var arr = [];
    snap.forEach(function(doc){ arr.push(Object.assign({uid:doc.id}, doc.data())); });
    arr.sort(function(a,b){ return (a.email||'').localeCompare(b.email||''); });
    allUsersCache = arr;
    return arr;
  });
}

function goAdmin(){
  view = 'admin';
  mainEl.innerHTML = '<p style="color:var(--text-faint);font-size:14px;padding:20px 0;">Cargando usuarios…</p>';
  allUsersCache = null;
  fetchAllUsers().then(renderAdmin).catch(function(){
    showToast('No se pudo cargar la lista de usuarios.', true);
  });
}

function renderAdmin(users){
  var rows = users.map(function(u){
    var isSelf = currentUser && u.uid===currentUser.uid;
    return '<div class="survey-card bracket">'+
      '<h3 style="font-size:15px;">'+escapeHtml(u.email)+(isSelf?' <span style="font-size:11px;color:var(--text-faint);">(tú)</span>':'')+'</h3>'+
      '<div class="meta">Alta: '+(u.createdAt ? new Date(u.createdAt).toLocaleDateString('es-MX') : '—')+'</div>'+
      '<div class="field-row" style="margin-top:10px;">'+
        '<label class="field"><span>Rol</span><select data-user-role="'+u.uid+'" '+(isSelf?'disabled':'')+'>'+
          '<option value="tecnico" '+(u.role==='tecnico'?'selected':'')+'>Usuario</option>'+
          '<option value="admin" '+(u.role==='admin'?'selected':'')+'>Administrador</option>'+
        '</select></label>'+
        '<p class="hint" style="margin-top:2px;">Usuario: Levantamiento y Costos. Administrador: además la Calculadora de material.</p>'+
        '<label class="field"><span>Estado</span><select data-user-disabled="'+u.uid+'" '+(isSelf?'disabled':'')+'>'+
          '<option value="false" '+(!u.disabled?'selected':'')+'>Activo</option>'+
          '<option value="true" '+(u.disabled?'selected':'')+'>Deshabilitado</option>'+
        '</select></label>'+
      '</div>'+
      (isSelf?'<p class="summary-empty-note">No puedes cambiar tu propio rol, estado, ni eliminarte a ti mismo.</p>':
        '<button type="button" class="btn danger" style="margin-top:6px;padding:8px 12px;font-size:13px;" data-user-delete="'+u.uid+'" data-user-email="'+escapeHtml(u.email)+'">Eliminar usuario</button>')+
    '</div>';
  }).join('');

  mainEl.innerHTML =
    '<div class="list-head"><h2 class="disp" style="font-size:19px;">Administración de usuarios</h2>'+
    '<button class="btn secondary" id="btn-admin-back">← Levantamientos</button></div>'+
    (rows ? '<div class="survey-grid">'+rows+'</div>' : '<div class="empty-state">Aún no hay usuarios registrados.</div>');

  document.getElementById('btn-admin-back').onclick = goList;
  mainEl.querySelectorAll('[data-user-role]').forEach(function(el){
    el.addEventListener('change', function(){
      updateUserField(el.dataset.userRole, {role: el.value});
    });
  });
  mainEl.querySelectorAll('[data-user-disabled]').forEach(function(el){
    el.addEventListener('change', function(){
      updateUserField(el.dataset.userDisabled, {disabled: el.value==='true'});
    });
  });
  mainEl.querySelectorAll('[data-user-delete]').forEach(function(el){
    el.addEventListener('click', function(){
      var uid = el.dataset.userDelete, email = el.dataset.userEmail;
      customConfirm('¿Eliminar a '+email+'? Ya no podrá iniciar sesión ni verse en esta lista. Sus levantamientos NO se borran.').then(function(ok){
        if(ok) deleteUserProfile(uid, email);
      });
    });
  });
}

function updateUserField(uid, changes){
  fbDb.collection('users').doc(uid).update(changes).then(function(){
    showToast('Usuario actualizado');
    allUsersCache = null;
  }).catch(function(){
    showToast('No se pudo actualizar. Intenta de nuevo.', true);
  });
}

function deleteUserProfile(uid, email){
  fbDb.collection('deletedUsers').doc(uid).set({email:email, deletedAt:Date.now()})
    .then(function(){ return fbDb.collection('users').doc(uid).delete(); })
    .then(function(){
      showToast('Usuario eliminado. Sus levantamientos se conservan.');
      allUsersCache = null;
      goAdmin();
    }).catch(function(){
      showToast('No se pudo eliminar. Intenta de nuevo.', true);
    });
}

/* ================= DATA MODEL HELPERS ================= */

function genFolio(ts){
  var d = new Date(ts || Date.now());
  function pad(n){ return (n<10?'0':'')+n; }
  var ymd = '' + d.getFullYear() + pad(d.getMonth()+1) + pad(d.getDate());
  var suffix = Math.random().toString(36).slice(2,5).toUpperCase();
  return 'SITI-' + ymd + '-' + suffix;
}
// Devuelve el folio del levantamiento; lo genera y fija si aún no existe.
function surveyFolio(s){
  if(!s) return '';
  if(!s.folio) s.folio = genFolio(s.createdAt);
  return s.folio;
}

function newSurveyState(){
  var now = Date.now();
  var s = {
    id: genId(),
    folio: genFolio(now),
    createdAt: now,
    updatedAt: now,
    general: {fecha: todayISO()},
    services: [],
    data: {}
  };
  if(backend==='firebase' && currentUser){
    s.ownerId = currentUser.uid;
    s.ownerEmail = currentUser.email;
  }
  return s;
}
function ensureServiceData(key){
  if(!current.data[key]) current.data[key] = {fields:{}, repeatable:{}};
  var conf = SERVICES[key];
  if(conf.repeatable && !current.data[key].repeatable[conf.repeatable.key]){
    current.data[key].repeatable[conf.repeatable.key] = [];
  }
}
function toggleService(key, checked){
  var idx = current.services.indexOf(key);
  if(checked && idx===-1) current.services.push(key);
  if(!checked && idx>-1) current.services.splice(idx,1);
  if(checked) ensureServiceData(key);
  renderForm();
}
function addRepItem(serviceKey, groupKey){
  ensureServiceData(serviceKey);
  current.data[serviceKey].repeatable[groupKey].push({});
  openAccordions[serviceKey] = true;
  renderForm();
}
function removeRepItem(serviceKey, groupKey, index){
  current.data[serviceKey].repeatable[groupKey].splice(index,1);
  renderForm();
}
function addCalDetItem(serviceKey, groupKey, itemIndex){
  var item = current.data[serviceKey].repeatable[groupKey][itemIndex];
  if(!item.canalizacion_detalle) item.canalizacion_detalle = [];
  item.canalizacion_detalle.push({});
  renderForm();
}
function removeCalDetItem(serviceKey, groupKey, itemIndex, k){
  current.data[serviceKey].repeatable[groupKey][itemIndex].canalizacion_detalle.splice(k,1);
  renderForm();
}
function addEnergiaDetItem(serviceKey, groupKey, itemIndex){
  var item = current.data[serviceKey].repeatable[groupKey][itemIndex];
  if(!item.energia_detalle) item.energia_detalle = [];
  item.energia_detalle.push({});
  renderForm();
}
function removeEnergiaDetItem(serviceKey, groupKey, itemIndex, k){
  current.data[serviceKey].repeatable[groupKey][itemIndex].energia_detalle.splice(k,1);
  renderForm();
}

/* ================= INPUT DELEGATION ================= */

function handleFormEvent(e){
  var t = e.target;

  if(t.type==='number' && t.value!=='' && Number(t.value)<0){
    t.value = 0;
  }

  if(t.dataset.caldetIndex!==undefined){
    var s = t.dataset.service, g = t.dataset.puntoGroup, pi = Number(t.dataset.puntoIndex), ci = Number(t.dataset.caldetIndex);
    var item = current.data[s].repeatable[g][pi];
    if(!item.canalizacion_detalle) item.canalizacion_detalle = [];
    if(!item.canalizacion_detalle[ci]) item.canalizacion_detalle[ci] = {};
    item.canalizacion_detalle[ci][t.dataset.field] = t.value;
    if(t.dataset.rerender!==undefined) renderForm();
    return;
  }

  if(t.dataset.endetIndex!==undefined){
    var s2 = t.dataset.service, g2 = t.dataset.puntoGroup, pi2 = Number(t.dataset.puntoIndex), ei = Number(t.dataset.endetIndex);
    var item2 = current.data[s2].repeatable[g2][pi2];
    if(!item2.energia_detalle) item2.energia_detalle = [];
    if(!item2.energia_detalle[ei]) item2.energia_detalle[ei] = {};
    item2.energia_detalle[ei][t.dataset.field] = t.value;
    if(t.dataset.rerender!==undefined) renderForm();
    return;
  }

  if(t.dataset.qtyOption!==undefined){
    ensureServiceData(t.dataset.service);
    var qf = current.data[t.dataset.service].fields;
    var qtyKey = t.dataset.field+'_qty';
    if(!qf[qtyKey]) qf[qtyKey] = {};
    qf[qtyKey][t.dataset.qtyOption] = t.value;
    return;
  }

  if(t.dataset.otherText!==undefined){
    ensureServiceData(t.dataset.service);
    current.data[t.dataset.service].fields[t.dataset.field+'_otro_texto'] = t.value;
    return;
  }

  if(t.dataset.general!==undefined){
    current.general[t.dataset.general] = t.value;
    if(t.dataset.general==='cliente') updateEmpresaUI(t.value);
    if(t.dataset.rerender!==undefined) renderForm();
    return;
  }

  if(t.dataset.service!==undefined && t.dataset.group===undefined && t.dataset.field!==undefined){
    ensureServiceData(t.dataset.service);
    if(t.type==='checkbox'){
      var arr = current.data[t.dataset.service].fields[t.dataset.field] || [];
      var v = t.dataset.value;
      var i = arr.indexOf(v);
      if(t.checked && i===-1) arr.push(v);
      if(!t.checked && i>-1) arr.splice(i,1);
      current.data[t.dataset.service].fields[t.dataset.field] = arr;
    } else {
      current.data[t.dataset.service].fields[t.dataset.field] = t.value;
    }
    if(t.dataset.rerender!==undefined) renderForm();
    return;
  }

  if(t.dataset.service!==undefined && t.dataset.group!==undefined && t.dataset.index!==undefined && t.dataset.field!==undefined){
    ensureServiceData(t.dataset.service);
    var idx = Number(t.dataset.index);
    current.data[t.dataset.service].repeatable[t.dataset.group][idx][t.dataset.field] = t.value;
    if(t.dataset.rerender!==undefined) renderForm();
    return;
  }
}

/* ================= FIELD RENDERING ================= */

var TRAILING_OPTION_TERMS = ['Por definir','No aplica','Otro','Otra','Por confirmar','Por verificar','Ninguna'];
function finalizeOptions(opts){
  var normal = [], trailing = [];
  opts.forEach(function(o){ (TRAILING_OPTION_TERMS.indexOf(o)>-1 ? trailing : normal).push(o); });
  return normal.concat(trailing);
}

function renderFieldInput(f, value, dataAttrs, otherValue){
  if(f.triggersRerender){ dataAttrs += ' data-rerender="1"'; }
  var val = (value===undefined||value===null) ? '' : value;
  if(f.type==='textarea'){
    return '<label class="field"><span>'+escapeHtml(f.label)+'</span><textarea '+dataAttrs+'>'+escapeHtml(val)+'</textarea></label>';
  }
  if(f.type==='select'){
    var selOpts = finalizeOptions(f.options);
    var emptyLabel = f.emptyLabel || '— Selecciona —';
    var opts = '<option value="">'+escapeHtml(emptyLabel)+'</option>' + selOpts.map(function(o){
      return '<option value="'+escapeHtml(o)+'" '+(o===val?'selected':'')+'>'+escapeHtml(o)+'</option>';
    }).join('');
    return '<label class="field"><span>'+escapeHtml(f.label)+'</span><select '+dataAttrs+'>'+opts+'</select></label>';
  }
  if(f.type==='checkbox-group'){
    var arr = Array.isArray(value) ? value : [];
    var cgOpts = finalizeOptions(f.options);
    var rerenderOptions = f.triggersRerenderOptions || (f.otherOption ? [f.otherOption] : []);
    var chips = cgOpts.map(function(o){
      var checked = arr.indexOf(o)>-1 ? 'checked' : '';
      var rrAttr = rerenderOptions.indexOf(o)>-1 ? ' data-rerender="1"' : '';
      return '<label class="chip-check"><input type="checkbox" '+dataAttrs+' data-value="'+escapeHtml(o)+'"'+rrAttr+' '+checked+'/> '+escapeHtml(o)+'</label>';
    }).join('');
    var otherHtml = '';
    if(f.otherOption && arr.indexOf(f.otherOption)>-1){
      var ov = otherValue || '';
      otherHtml = '<input type="text" class="other-text-input" placeholder="'+escapeHtml(f.otherLabel||'Especifique')+'" '+dataAttrs+' data-other-text="1" value="'+escapeHtml(ov)+'"/>';
    }
    return '<div class="field"><span>'+escapeHtml(f.label)+'</span><div class="chip-check-group">'+chips+'</div>'+otherHtml+'</div>';
  }
  var type = f.type==='number' ? 'number' : (f.type==='date' ? 'date' : 'text');
  var extra = f.type==='number' ? ' min="0"' : '';
  if(f.autocompleteEmpresa){
    extra += ' list="empresas-datalist" autocomplete="off"';
    var hintTxt = empresaHintText(val);
    var foundCls = empresaExiste((val||'').trim()) ? ' found' : '';
    return '<label class="field"><span>'+escapeHtml(f.label)+'</span>'+
      '<input type="'+type+'"'+extra+' '+dataAttrs+' value="'+escapeHtml(val)+'"/>'+
      '<small class="empresa-hint'+foundCls+'" data-empresa-hint>'+escapeHtml(hintTxt)+'</small></label>';
  }
  return '<label class="field"><span>'+escapeHtml(f.label)+'</span><input type="'+type+'"'+extra+' '+dataAttrs+' value="'+escapeHtml(val)+'"/></label>';
}

function renderGeneralSection(){
  var visible = GENERAL_FIELDS.filter(function(f){ return passesShowIf(f, current.general); });
  var html = '';
  for(var i=0;i<visible.length;i++){
    var f = visible[i];
    var attrs = 'data-general="'+f.key+'"';
    if(f.pairWithNext && visible[i+1]){
      var f2 = visible[i+1];
      var html1 = renderFieldInput(f, current.general[f.key], attrs);
      var html2 = renderFieldInput(f2, current.general[f2.key], 'data-general="'+f2.key+'"');
      html += '<div class="field-row">'+html1+html2+'</div>';
      i++;
      continue;
    }
    html += renderFieldInput(f, current.general[f.key], attrs);
  }
  var datalist = '<datalist id="empresas-datalist">'+empresasNames.map(function(n){
    return '<option value="'+escapeHtml(n)+'"></option>';
  }).join('')+'</datalist>';
  return '<div class="section"><div class="sec-title disp">Datos generales del sitio</div><div class="sec-body">'+html+datalist+'</div></div>';
}

function renderServiceSelector(){
  var cards = SERVICE_ORDER.map(function(key){
    var checked = current.services.indexOf(key)>-1;
    return '<label class="service-card"><input type="checkbox" data-service-toggle="'+key+'" '+(checked?'checked':'')+'/><span class="box"></span><span>'+escapeHtml(SERVICES[key].label)+'</span></label>';
  }).join('');
  return '<div class="section"><div class="sec-title disp">Servicios a cotizar</div><div class="sec-body"><div class="service-grid">'+cards+'</div></div></div>';
}

var CANALIZACION_TIPOS = ['Canaleta','Charola','PVC Ced. 40','PVC Pesado','Tubería E/A','Tubería E/V','Otro'];
var TUBERIA_TIPOS = ['Tubería E/V','Tubería E/A','PVC Pesado','PVC Ced. 40'];

function medidaOptionsForTipo(tipo){
  if(TUBERIA_TIPOS.indexOf(tipo)>-1) return ['1/2"','3/4"','1"','1 1/4"','1 1/2"','2"'];
  if(tipo==='Canaleta') return ['LD3','LD5','LD15','T45','T70'];
  if(tipo==='Charola') return ['50mm','100mm','150mm','200mm','250mm','300mm'];
  return null;
}

function renderCanalizacionDetalle(serviceKey, groupKey, itemIndex, item){
  var rows = item.canalizacion_detalle || [];
  var rowsHtml = rows.map(function(row, k){
    var base = 'data-service="'+serviceKey+'" data-punto-group="'+groupKey+'" data-punto-index="'+itemIndex+'" data-caldet-index="'+k+'"';
    var tipoField = renderFieldInput({key:'tipo', label:'Tipo de canalización', type:'select', options:CANALIZACION_TIPOS, triggersRerender:true}, row.tipo, base+' data-field="tipo"');
    var medidaOpts = medidaOptionsForTipo(row.tipo);
    var medidaField = medidaOpts ? renderFieldInput({key:'medida', label:'Medida', type:'select', options:medidaOpts}, row.medida, base+' data-field="medida"') : '';
    var distField = renderFieldInput({key:'distancia', label:'Distancia (m)', type:'number'}, row.distancia, base+' data-field="distancia"');
    var obsField = renderFieldInput({key:'observaciones', label:'Observaciones', type:'textarea'}, row.observaciones, base+' data-field="observaciones"');
    return '<div class="rep-item"><div class="rep-head"><strong>Canalización '+(k+1)+'</strong>'+
      '<button type="button" class="rep-remove" data-remove-caldet="'+serviceKey+'|'+groupKey+'|'+itemIndex+'|'+k+'">Eliminar</button></div>'+
      '<div class="field-row">'+tipoField+medidaField+'</div>'+distField+obsField+'</div>';
  }).join('');
  return '<div class="rep-list"><div class="field"><span>Detalle de canalización para esta ruta</span></div>'+rowsHtml+
    '<button type="button" class="btn ghost add-item" data-add-caldet="'+serviceKey+'|'+groupKey+'|'+itemIndex+'">+ Agregar tipo de canalización</button></div>';
}

var ELECTRICO_TIPOS = ['Cable Dúplex','Cable THHW','Cable THW-LS','Extensión eléctrica','Otro'];
var CALIBRE_AWG = ['8 AWG','10 AWG','12 AWG','14 AWG','16 AWG','18 AWG'];

function renderEnergiaDetalle(serviceKey, groupKey, itemIndex, item){
  var rows = item.energia_detalle || [];
  var rowsHtml = rows.map(function(row, k){
    var base = 'data-service="'+serviceKey+'" data-punto-group="'+groupKey+'" data-punto-index="'+itemIndex+'" data-endet-index="'+k+'"';
    var tipoField = renderFieldInput({key:'tipo', label:'Tipo de conductor', type:'select', options:ELECTRICO_TIPOS}, row.tipo, base+' data-field="tipo"');
    var calibreField = renderFieldInput({key:'calibre', label:'Calibre', type:'select', options:CALIBRE_AWG}, row.calibre, base+' data-field="calibre"');
    var canTipoField = renderFieldInput({key:'canalizacion_tipo', label:'Tipo de canalización', type:'select', options:CANALIZACION_TIPOS, triggersRerender:true}, row.canalizacion_tipo, base+' data-field="canalizacion_tipo"');
    var canMedidaOpts = medidaOptionsForTipo(row.canalizacion_tipo);
    var canMedidaField = canMedidaOpts ? renderFieldInput({key:'canalizacion_medida', label:'Medida', type:'select', options:canMedidaOpts}, row.canalizacion_medida, base+' data-field="canalizacion_medida"') : '';
    var distField = renderFieldInput({key:'distancia', label:'Distancia (m)', type:'number'}, row.distancia, base+' data-field="distancia"');
    var obsField = renderFieldInput({key:'observaciones', label:'Observaciones', type:'textarea'}, row.observaciones, base+' data-field="observaciones"');
    return '<div class="rep-item"><div class="rep-head"><strong>Tramo eléctrico '+(k+1)+'</strong>'+
      '<button type="button" class="rep-remove" data-remove-endet="'+serviceKey+'|'+groupKey+'|'+itemIndex+'|'+k+'">Eliminar</button></div>'+
      '<div class="field-row">'+tipoField+calibreField+'</div>'+
      '<div class="field-row">'+canTipoField+canMedidaField+'</div>'+distField+obsField+'</div>';
  }).join('');
  return '<div class="rep-list"><div class="field"><span>Detalle de corriente eléctrica para esta ruta</span></div>'+rowsHtml+
    '<button type="button" class="btn ghost add-item" data-add-endet="'+serviceKey+'|'+groupKey+'|'+itemIndex+'">+ Agregar tramo eléctrico</button></div>';
}

function renderRepeatable(serviceKey, conf){
  var rep = conf.repeatable;
  if(!rep) return '';
  ensureServiceData(serviceKey);
  var items = current.data[serviceKey].repeatable[rep.key] || [];
  var itemsHtml = items.map(function(item, idx){
    var fieldsHtml = rep.fields.map(function(f){
      if(!passesShowIf(f, item)) return '';
      var fieldDef = f;
      if(f.optionsByValue){
        var triggerVal = item[f.optionsByValue.field];
        var opts = f.optionsByValue.map[triggerVal] || [];
        if(!opts.length) return '';
        fieldDef = Object.assign({}, f, {options:opts});
      }
      // Cable: si no se define en el punto, hereda la categoría del servicio.
      var svcCat = serviceCableCat(serviceKey);
      if(f.inheritCable && svcCat){
        fieldDef = Object.assign({}, fieldDef, {emptyLabel:'Igual a la del servicio ('+svcCat+')'});
      }
      var attrs = 'data-service="'+serviceKey+'" data-group="'+rep.key+'" data-index="'+idx+'" data-field="'+f.key+'"';
      return renderFieldInput(fieldDef, item[f.key], attrs);
    }).join('');
    var extra = '';
    if(rep.hasCanalizacionDetail && (item.canalizacion==='Parcial' || item.canalizacion==='Sí')){
      extra += renderCanalizacionDetalle(serviceKey, rep.key, idx, item);
    }
    if(rep.hasEnergiaDetail && item.energia_cercana==='No'){
      extra += renderEnergiaDetalle(serviceKey, rep.key, idx, item);
    }
    return '<div class="rep-item"><div class="rep-head"><strong>'+rep.itemLabel+' '+(idx+1)+'</strong>'+
      '<button type="button" class="rep-remove" data-remove-rep="'+serviceKey+'|'+rep.key+'|'+idx+'">Eliminar</button></div>'+
      fieldsHtml+extra+'</div>';
  }).join('');
  var addLabel = rep.addLabel || ('+ Agregar '+rep.itemLabel.toLowerCase());
  return '<div class="rep-list"><div class="field"><span>'+escapeHtml(rep.label)+'</span></div>'+itemsHtml+
    '<button type="button" class="btn ghost add-item" data-add-rep="'+serviceKey+'|'+rep.key+'">'+addLabel+'</button></div>';
}

function renderCheckboxQtyField(key, f){
  var fields = current.data[key].fields;
  var selected = Array.isArray(fields[f.key]) ? fields[f.key] : [];
  var qty = fields[f.key+'_qty'] || {};
  var noQty = f.noQty || [];
  var rows = finalizeOptions(f.options).map(function(o){
    var checked = selected.indexOf(o)>-1;
    var qtyHtml = '';
    if(checked && noQty.indexOf(o)===-1){
      var qv = (qty[o]!==undefined && qty[o]!==null) ? qty[o] : '';
      qtyHtml = '<input type="number" min="0" class="qty-input" placeholder="Cantidad" data-service="'+key+'" data-field="'+f.key+'" data-qty-option="'+escapeHtml(o)+'" value="'+escapeHtml(qv)+'"/>';
    }
    return '<div class="qty-row"><label class="chip-check"><input type="checkbox" data-service="'+key+'" data-field="'+f.key+'" data-value="'+escapeHtml(o)+'" data-rerender="1" '+(checked?'checked':'')+'/> '+escapeHtml(o)+'</label>'+qtyHtml+'</div>';
  }).join('');
  return '<div class="field"><span>'+escapeHtml(f.label)+'</span><div class="qty-group">'+rows+'</div></div>';
}

function renderTopFields(key, conf){
  var flds = conf.fields;
  var html = '';
  for(var i=0;i<flds.length;i++){
    var f = flds[i];
    if(!passesShowIf(f, current.data[key].fields)) continue;
    if(f.type==='checkbox-qty'){
      html += renderCheckboxQtyField(key, f);
      continue;
    }
    var fieldDef = f;
    if(f.extraOptionsIf && passesShowIf({showIf:f.extraOptionsIf}, current.data[key].fields)){
      fieldDef = Object.assign({}, f, {options: f.options.concat(f.extraOptionsIf.options)});
    }
    var attrs1 = 'data-service="'+key+'" data-field="'+f.key+'"';
    if(f.pairWithNext && flds[i+1]){
      var f2 = flds[i+1];
      var html1 = renderFieldInput(fieldDef, current.data[key].fields[f.key], attrs1);
      var html2 = renderFieldInput(f2, current.data[key].fields[f2.key], 'data-service="'+key+'" data-field="'+f2.key+'"');
      html += '<div class="field-row">'+html1+html2+'</div>';
      i++;
      continue;
    }
    html += renderFieldInput(fieldDef, current.data[key].fields[f.key], attrs1, current.data[key].fields[f.key+'_otro_texto']);
  }
  return html;
}

function renderServiceAccordion(key){
  var conf = SERVICES[key];
  ensureServiceData(key);
  var isOpen = !!openAccordions[key];
  var fieldsHtml = renderTopFields(key, conf);
  var repHtml = renderRepeatable(key, conf);
  return '<div class="section accordion '+(isOpen?'open':'')+'">'+
    '<button type="button" class="accordion-head" data-toggle-acc="'+key+'"><h3>'+escapeHtml(conf.label)+'</h3><span class="arrow">▸</span></button>'+
    '<div class="accordion-body" '+(isOpen?'':'hidden')+'>'+fieldsHtml+repHtml+'</div>'+
  '</div>';
}

function renderForm(){
  var scrollY = window.scrollY;
  var html = '<h2 class="disp" style="font-size:19px;margin-bottom:16px;">'+(current._isNew?'Nuevo levantamiento':'Editar levantamiento')+'</h2>';
  html += renderGeneralSection();
  html += renderServiceSelector();
  current.services.forEach(function(key){
    html += renderServiceAccordion(key);
  });
  mainEl.innerHTML = html;
  attachFormHandlers();

  var bar = document.createElement('div');
  bar.className = 'action-bar noprint';
  bar.innerHTML = '<button class="btn secondary" id="btn-cancel-form">Cancelar</button><button class="btn" id="btn-save-form">Guardar levantamiento</button>';
  mainEl.appendChild(bar);
  window.scrollTo(0, scrollY);
  document.getElementById('btn-cancel-form').onclick = function(){
    customConfirm('¿Descartar los cambios de este levantamiento?').then(function(ok){ if(ok) goList(); });
  };
  document.getElementById('btn-save-form').onclick = doSave;
}

function attachFormHandlers(){
  var toggles = mainEl.querySelectorAll('[data-service-toggle]');
  toggles.forEach(function(el){
    el.addEventListener('change', function(){
      toggleService(el.dataset.serviceToggle, el.checked);
    });
  });
  var accHeads = mainEl.querySelectorAll('[data-toggle-acc]');
  accHeads.forEach(function(el){
    el.addEventListener('click', function(){
      var key = el.dataset.toggleAcc;
      openAccordions[key] = !openAccordions[key];
      var section = el.parentElement;
      var body = section.querySelector('.accordion-body');
      if(openAccordions[key]){
        section.classList.add('open');
        body.removeAttribute('hidden');
      } else {
        section.classList.remove('open');
        body.setAttribute('hidden','');
      }
    });
  });
  var addBtns = mainEl.querySelectorAll('[data-add-rep]');
  addBtns.forEach(function(el){
    el.addEventListener('click', function(){
      var parts = el.dataset.addRep.split('|');
      addRepItem(parts[0], parts[1]);
    });
  });
  var rmBtns = mainEl.querySelectorAll('[data-remove-rep]');
  rmBtns.forEach(function(el){
    el.addEventListener('click', function(){
      var parts = el.dataset.removeRep.split('|');
      customConfirm('¿Eliminar este elemento?').then(function(ok){
        if(ok) removeRepItem(parts[0], parts[1], Number(parts[2]));
      });
    });
  });
  var addCalBtns = mainEl.querySelectorAll('[data-add-caldet]');
  addCalBtns.forEach(function(el){
    el.addEventListener('click', function(){
      var parts = el.dataset.addCaldet.split('|');
      addCalDetItem(parts[0], parts[1], Number(parts[2]));
    });
  });
  var rmCalBtns = mainEl.querySelectorAll('[data-remove-caldet]');
  rmCalBtns.forEach(function(el){
    el.addEventListener('click', function(){
      var parts = el.dataset.removeCaldet.split('|');
      removeCalDetItem(parts[0], parts[1], Number(parts[2]), Number(parts[3]));
    });
  });
  var addEnBtns = mainEl.querySelectorAll('[data-add-endet]');
  addEnBtns.forEach(function(el){
    el.addEventListener('click', function(){
      var parts = el.dataset.addEndet.split('|');
      addEnergiaDetItem(parts[0], parts[1], Number(parts[2]));
    });
  });
  var rmEnBtns = mainEl.querySelectorAll('[data-remove-endet]');
  rmEnBtns.forEach(function(el){
    el.addEventListener('click', function(){
      var parts = el.dataset.removeEndet.split('|');
      removeEnergiaDetItem(parts[0], parts[1], Number(parts[2]), Number(parts[3]));
    });
  });
}

function doSave(){
  if(!current.general.cliente || !current.general.cliente.trim()){
    showToast('Ingresa al menos el nombre del cliente antes de guardar.', true);
    return;
  }
  if(current.services.length===0){
    showToast('Selecciona al menos un servicio a cotizar.', true);
    return;
  }
  current.updatedAt = Date.now();
  delete current._isNew;
  upsertIndexEntry(current);
  Promise.all([persistSurvey(current), saveIndex(), upsertEmpresa(current.general)]).then(function(){
    showToast('Levantamiento guardado');
    goSummary(current.id);
  }).catch(function(){
    showToast('No se pudo guardar. Intenta de nuevo.', true);
  });
}

/* ================= LIST VIEW ================= */

function renderList(){
  var isAdminAll = backend==='firebase' && currentUser && currentUser.role==='admin';
  var html = '<div class="list-head"><h2 class="disp" style="font-size:19px;">Levantamientos guardados</h2>'+
    '<button class="btn" id="btn-new">+ Nuevo</button></div>';

  if(isAdminAll){
    html += '<div class="field" style="max-width:340px;margin-bottom:14px;"><span>Ver levantamientos de</span>'+
      '<select id="admin-owner-filter"><option value="ALL">Todos los técnicos</option></select></div>';
  }

  if(indexData.length===0){
    html += '<div class="empty-state">Aún no hay levantamientos. Toca "+ Nuevo" para capturar el primero en sitio.</div>';
  } else {
    var sorted = indexData.slice().sort(function(a,b){ return (b.updatedAt||0)-(a.updatedAt||0); });
    html += '<div class="survey-grid">' + sorted.map(function(e){
      var chips = e.services.map(function(s){ return '<span class="chip">'+escapeHtml(SERVICES[s]?SERVICES[s].short:s)+'</span>'; }).join('');
      var ownerBadge = (isAdminAll && adminFilterOwnerId==='ALL' && e.ownerEmail) ? '<div class="meta">Capturado por: '+escapeHtml(e.ownerEmail)+'</div>' : '';
      return '<div class="survey-card bracket">'+
        '<h3>'+escapeHtml(e.cliente)+'</h3>'+
        '<div class="meta">'+escapeHtml(e.direccion||'Sin dirección')+' · '+fmtDate(e.fecha)+(e.tecnico?' · '+escapeHtml(e.tecnico):'')+'</div>'+
        ownerBadge+
        '<div class="chips">'+chips+'</div>'+
        '<div class="card-actions">'+
          '<button class="btn ghost" data-open="'+e.id+'">Ver resumen</button>'+
          '<button class="btn ghost" data-edit="'+e.id+'">Editar</button>'+
          '<button class="btn danger" data-del="'+e.id+'">Eliminar</button>'+
        '</div></div>';
    }).join('') + '</div>';
  }
  mainEl.innerHTML = html;

  if(isAdminAll){
    fetchAllUsers().then(function(users){
      var sel = document.getElementById('admin-owner-filter');
      if(!sel) return;
      users.forEach(function(u){
        var opt = document.createElement('option');
        opt.value = u.uid; opt.textContent = u.email;
        if(u.uid===adminFilterOwnerId) opt.selected = true;
        sel.appendChild(opt);
      });
      sel.value = adminFilterOwnerId;
      sel.addEventListener('change', function(){
        adminFilterOwnerId = sel.value;
        goList();
      });
    });
  }

  var newBtn = document.getElementById('btn-new');
  if(newBtn) newBtn.onclick = function(){
    current = newSurveyState();
    current._isNew = true;
    openAccordions = {};
    view='form'; renderForm();
  };
  mainEl.querySelectorAll('[data-open]').forEach(function(el){
    el.onclick = function(){ goSummary(el.dataset.open); };
  });
  mainEl.querySelectorAll('[data-edit]').forEach(function(el){
    el.onclick = function(){ goEdit(el.dataset.edit); };
  });
  mainEl.querySelectorAll('[data-del]').forEach(function(el){
    el.onclick = function(){
      var id = el.dataset.del;
      customConfirm('¿Eliminar este levantamiento? Esta acción no se puede deshacer.').then(function(ok){
        if(!ok) return;
        removeSurveyStorage(id).then(function(){
          indexData = indexData.filter(function(e){ return e.id!==id; });
          return saveIndex();
        }).then(function(){ showToast('Levantamiento eliminado'); renderList(); })
          .catch(function(){ showToast('No se pudo eliminar.', true); });
      });
    };
  });
}

function goList(){
  view='list';
  mainEl.innerHTML = '<p style="color:var(--text-faint);font-size:14px;padding:20px 0;">Cargando levantamientos…</p>';
  loadIndex().then(function(data){
    indexData = data;
    if(view==='list') renderList();
  }).catch(function(){
    indexData = [];
    if(view==='list') renderList();
    showToast('No se pudieron cargar los levantamientos.', true);
  });
}

function goEdit(id){
  loadSurvey(id).then(function(s){
    if(!s){ showToast('No se encontró el levantamiento.', true); return; }
    current = s;
    current._isNew = false;
    if(!current.data) current.data = {};
    if(!current.services) current.services = [];
    openAccordions = {};
    current.services.forEach(function(k){ openAccordions[k]=false; });
    if(current.services.length) openAccordions[current.services[0]] = true;
    view='form'; renderForm();
  });
}

/* ================= SUMMARY / PRINT VIEW ================= */

function fieldValueText(f, value){
  if(value===undefined||value===null||value===''||( Array.isArray(value) && value.length===0)) return '';
  if(f.type==='checkbox-group') return value.join(', ');
  if(f.type==='date') return fmtDate(value);
  return String(value);
}
// Categoría de cableado definida a nivel del servicio (ej. en Nodos de red).
function serviceCableCat(serviceKey){
  var d = current.data[serviceKey];
  return (d && d.fields && d.fields.cable_categoria) || '';
}
// Valor de un campo de punto para el resumen/exportación, resolviendo la
// herencia del cable (si el punto no lo define, usa la categoría del servicio).
function itemFieldValue(f, item, serviceKey){
  var v = item[f.key];
  if(f.inheritCable && (v===undefined||v===null||v==='')) return serviceCableCat(serviceKey);
  return v;
}

function canalizacionDetailText(item){
  var rows = item.canalizacion_detalle || [];
  if(!rows.length) return '';
  return rows.map(function(r){
    var t = r.tipo || 'Tipo por definir';
    var m = r.medida ? ' '+r.medida : '';
    var d = r.distancia ? ' ('+r.distancia+'m)' : '';
    var o = r.observaciones ? ' — '+r.observaciones : '';
    return t+m+d+o;
  }).join('; ');
}

function energiaDetailText(item){
  var rows = item.energia_detalle || [];
  if(!rows.length) return '';
  return rows.map(function(r){
    var t = r.tipo || 'Tipo por definir';
    var c = r.calibre ? ' '+r.calibre : '';
    var ct = r.canalizacion_tipo ? ', canalización: '+r.canalizacion_tipo : '';
    var cm = r.canalizacion_medida ? ' '+r.canalizacion_medida : '';
    var d = r.distancia ? ' ('+r.distancia+'m)' : '';
    var o = r.observaciones ? ' — '+r.observaciones : '';
    return t+c+ct+cm+d+o;
  }).join('; ');
}

function checkboxQtyText(f, dataFields){
  var arr = Array.isArray(dataFields[f.key]) ? dataFields[f.key] : [];
  if(!arr.length) return '';
  var qty = dataFields[f.key+'_qty'] || {};
  var noQty = f.noQty || [];
  return arr.map(function(o){
    if(noQty.indexOf(o)>-1) return o;
    var q = qty[o];
    return q ? (o+' ('+q+' pza.)') : o;
  }).join(', ');
}

function withOtherText(f, dataFields, v){
  if(f.otherOption && v){
    var arr = dataFields[f.key];
    if(Array.isArray(arr) && arr.indexOf(f.otherOption)>-1){
      var ot = dataFields[f.key+'_otro_texto'];
      if(ot) v += ' ('+ot+')';
    }
  }
  return v;
}

/* ============ CONSOLIDADO DE MATERIALES Y CANTIDADES POR SOLUCIÓN ============ */
function numVal(v){ var n = parseFloat(v); return isNaN(n) ? 0 : n; }
function fmtQty(n){ return String(Math.round(n*100)/100); }
function repFieldDef(rep, fk){
  for(var i=0;i<rep.fields.length;i++){ if(rep.fields[i].key===fk) return rep.fields[i]; }
  return {key:fk};
}
function pluralUnit(n, singular){
  if(n===1) return singular;
  var map = {'punto':'puntos','tramo':'tramos'};
  return map[singular] || (singular+'s');
}
// Devuelve los bloques consolidados de un servicio (suma materiales iguales).
function consolidarServicio(key){
  var conf = SERVICES[key];
  var d = current.data[key] || {fields:{}, repeatable:{}};
  var blocks = [];

  // Cantidades numéricas capturadas a nivel del servicio (ej. Nodos a cotizar).
  var qtyRows = conf.fields.filter(function(f){ return f.type==='number'; }).map(function(f){
    var v = d.fields[f.key];
    return (v!==undefined && v!=='' && numVal(v)!==0) ? {label:f.label, value:fmtQty(numVal(v))} : null;
  }).filter(Boolean);
  if(qtyRows.length) blocks.push({title:'Cantidades', kind:'kv', rows:qtyRows});

  var rep = conf.repeatable;
  if(rep){
    var items = (d.repeatable && d.repeatable[rep.key]) || [];
    var bom = rep.bom || {};
    if(items.length){
      var groupBy = bom.groupBy || [];
      var sums = bom.sums || [];
      var groups = {}; var order = [];
      items.forEach(function(it){
        var sig = groupBy.length
          ? groupBy.map(function(fk){ return itemFieldValue(repFieldDef(rep,fk), it, key) || '—'; }).join(' · ')
          : 'Total';
        if(!groups[sig]){ groups[sig] = {count:0, sums:{}}; order.push(sig); }
        groups[sig].count++;
        sums.forEach(function(s){ groups[sig].sums[s.key] = (groups[sig].sums[s.key]||0) + numVal(it[s.key]); });
      });
      blocks.push({title: rep.itemLabel+'s', kind:'items', rows: order.map(function(sig){
        var g = groups[sig];
        var extra = sums.map(function(s){ return g.sums[s.key] ? fmtQty(g.sums[s.key])+' '+s.label : null; }).filter(Boolean).join(' · ');
        return {label: groupBy.length ? sig : 'Total', count:g.count, extra:extra};
      })});

      // Cable por categoría efectiva (metros = suma de distancias).
      if(bom.cableField){
        var cg = {}; var corder = [];
        items.forEach(function(it){
          var cat = itemFieldValue(repFieldDef(rep,bom.cableField), it, key) || '(sin especificar)';
          if(!cg[cat]){ cg[cat] = {count:0, m:0}; corder.push(cat); }
          cg[cat].count++; cg[cat].m += numVal(it.distancia);
        });
        var marca = d.fields.cable_marca ? (d.fields.cable_marca==='Otro' ? (d.fields.cable_marca_otro||'Otro') : d.fields.cable_marca) : '';
        blocks.push({title:'Cable'+(marca?' · '+marca:''), kind:'metros', unit:'punto',
          rows: corder.map(function(c){ return {label:c, count:cg[c].count, m:cg[c].m}; })});
      }

      // Canalización consolidada (tipo + medida) → metros.
      if(rep.hasCanalizacionDetail){
        var can = {}; var korder = [];
        items.forEach(function(it){
          (it.canalizacion_detalle||[]).forEach(function(r){
            if(!r.tipo && !r.medida && !numVal(r.distancia)) return;
            var kk = (r.tipo||'—')+(r.medida?' '+r.medida:'');
            if(!can[kk]){ can[kk] = {count:0, m:0}; korder.push(kk); }
            can[kk].count++; can[kk].m += numVal(r.distancia);
          });
        });
        if(korder.length) blocks.push({title:'Canalización', kind:'metros', unit:'tramo',
          rows: korder.map(function(k2){ return {label:k2, count:can[k2].count, m:can[k2].m}; })});
      }

      // Corriente eléctrica consolidada.
      if(rep.hasEnergiaDetail){
        var en = {}; var eorder = [];
        items.forEach(function(it){
          (it.energia_detalle||[]).forEach(function(r){
            if(!r.tipo && !r.calibre && !numVal(r.distancia)) return;
            var kk = [r.tipo||'—', r.calibre||'', r.canalizacion_tipo?('en '+r.canalizacion_tipo+(r.canalizacion_medida?' '+r.canalizacion_medida:'')):''].filter(Boolean).join(' · ');
            if(!en[kk]){ en[kk] = {count:0, m:0}; eorder.push(kk); }
            en[kk].count++; en[kk].m += numVal(r.distancia);
          });
        });
        if(eorder.length) blocks.push({title:'Corriente eléctrica', kind:'metros', unit:'tramo',
          rows: eorder.map(function(k3){ return {label:k3, count:en[k3].count, m:en[k3].m}; })});
      }
    }
  }
  return blocks;
}
function consBlockRight(b, r){
  if(b.kind==='kv') return String(r.value);
  if(b.kind==='items') return r.count + (r.extra ? ' · '+r.extra : '');
  var u = pluralUnit(r.count, b.unit);
  return r.count+' '+u + (r.m ? ' · '+fmtQty(r.m)+' m' : '');
}

